}

import {useEffect, useState} from 'react';
function Component() {
  const [firstName] = useState('Taylor');
  const [lastName] = useState('Swift');
  const [fullName, setFullName] = useState('');
  useEffect(() => {
    setFullName(firstName + ' ' + lastName);
  }, [firstName, lastName]);
  return <div>{fullName}</div>;
}

